import { Order, OrderSnapshot } from '../domain/Order';
import { OrderRepository } from '../domain/OrderRepository';
import { OrderStatus } from '../domain/OrderStatus';

/** Stores snapshots so callers never share mutable entity instances. */
export class InMemoryOrderRepository implements OrderRepository {
  private readonly rows = new Map<string, OrderSnapshot>();

  findById(id: string): Order | undefined {
    const row = this.rows.get(id);
    return row ? Order.restore(row) : undefined;
  }

  findByStatus(status: OrderStatus): Order[] {
    return [...this.rows.values()].filter((row) => row.status === status).map((row) => Order.restore(row));
  }

  findAll(): Order[] {
    return [...this.rows.values()].map((row) => Order.restore(row));
  }

  save(order: Order): void {
    this.rows.set(order.id, order.toSnapshot());
  }
}

